/* muscles.js - muscles model with tendons + procedural muscle-fibre anatomy texture.
 * Needs Three.js (r128+). Works as <script> (window.createMuscles) or CommonJS.
 *   const mesh = createMuscles(THREE, {height:1.75});  scene.add(mesh);
 *   mesh.userData.uniforms.uTendon.value = 0..1   // tendon visibility
 *   mesh.userData.uniforms.uFiber.value  = 0..1   // fibre/seam texture strength
 * Y-up, feet at y=0, X centered, front = +Z. */
(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.createMuscles=factory();})(typeof self!=='undefined'?self:this,function(){
const DATA="",TEND="",FDIR="";
const u8=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const NOISE=`
float h31(vec3 p){p=fract(p*.3183099+.1);p*=17.;return fract(p.x*p.y*p.z*(p.x+p.y+p.z));}
float vn(vec3 x){vec3 i=floor(x),f=fract(x);f=f*f*(3.-2.*f);
return mix(mix(mix(h31(i),h31(i+vec3(1,0,0)),f.x),mix(h31(i+vec3(0,1,0)),h31(i+vec3(1,1,0)),f.x),f.y),
mix(mix(h31(i+vec3(0,0,1)),h31(i+vec3(1,0,1)),f.x),mix(h31(i+vec3(0,1,1)),h31(i+vec3(1,1,1)),f.x),f.y),f.z);}
vec3 pNA(vec3 sp,vec3 sn,vec2 d){vec3 sx=dFdx(sp),sy=dFdy(sp);vec3 r1=cross(sy,sn),r2=cross(sn,sx);float det=dot(sx,r1);
vec3 g=sign(det)*(d.x*r1+d.y*r2);return normalize(abs(det)*sn-g);}`;
return function createMuscles(THREE,opt){
  opt=opt||{};const H=opt.height||1.75;
  const raw=u8(DATA).buffer,hd=new Uint32Array(raw,0,2),nv=hd[0],nt=hd[1];
  const q=new Int16Array(raw,8,nv*3),ix=new Uint16Array(raw,8+nv*6,nt*3),pos=new Float32Array(nv*3);
  const X0=0.11,Y0=0.35,k=H/163.94;
  for(let i=0;i<nv;i++){pos[i*3]=(q[i*3]*.01-X0)*k;pos[i*3+1]=(q[i*3+1]*.01-Y0)*k;pos[i*3+2]=q[i*3+2]*.01*k}
  const ten=u8(TEND),fd8=new Int8Array(u8(FDIR).buffer),tend=new Float32Array(nv),fdir=new Float32Array(nv*3);
  for(let i=0;i<nv;i++){tend[i]=ten[i]/255;fdir[i*3]=fd8[i*3]/127;fdir[i*3+1]=fd8[i*3+1]/127;fdir[i*3+2]=fd8[i*3+2]/127}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(pos,3));
  g.setAttribute('tend',new THREE.BufferAttribute(tend,1));g.setAttribute('fdir',new THREE.BufferAttribute(fdir,3));
  g.setIndex(new THREE.BufferAttribute(ix,1));g.computeVertexNormals();
  const U={uTendon:{value:1},uFiber:{value:1}};
  const mat=new THREE.MeshStandardMaterial({color:0xffffff,roughness:.55,metalness:.02});
  mat.onBeforeCompile=sh=>{Object.assign(sh.uniforms,U);
    sh.vertexShader=sh.vertexShader.replace('void main() {','attribute float tend;attribute vec3 fdir;uniform float uTendon;varying vec3 vP;varying vec3 vF;varying float vT;\nvoid main() {')
      .replace('#include <begin_vertex>','#include <begin_vertex>\nvP=position;vF=fdir;vT=tend*uTendon;transformed+=normal*vT*.0016;');
    sh.fragmentShader=sh.fragmentShader.replace('void main() {','uniform float uFiber;varying vec3 vP;varying vec3 vF;varying float vT;float gH=0.;\n'+NOISE+'\nvoid main() {')
      .replace('#include <color_fragment>',`#include <color_fragment>
      {vec3 d=normalize(vF);vec3 q=vP-d*dot(vP,d)*.88;           // stretch noise along fibre direction
       float fib=vn(q*200.)*.6+vn(q*430.)*.4;                     // fine fibres
       float bel=vn(q*45.+3.);                                     // muscle bellies
       float seam=1.-abs(2.*vn(q*18.+9.)-1.);seam=smoothstep(.82,1.,seam); // fascia seams between muscles
       vec3 deep=vec3(.36,.07,.10),mid=vec3(.70,.16,.20),hi=vec3(.80,.27,.28);
       vec3 m=mix(deep,mid,smoothstep(.2,.8,bel));m=mix(m,hi,smoothstep(.55,.95,fib)*.5);
       m*=.8+.4*fib;m=mix(m,vec3(.86,.62,.56),seam*.55);
       m=mix(vec3(.62,.15,.19),m,uFiber);
       vec3 tc=mix(vec3(.93,.87,.74),vec3(.98,.95,.88),vn(q*400.));
       float t=smoothstep(.12,.7,vT);
       diffuseColor.rgb=mix(m,tc,t);
       gH=mix((fib-.5)*.9*uFiber-seam*1.3*uFiber,(fib-.5)*1.6,t);}`)
      .replace('#include <roughnessmap_fragment>','#include <roughnessmap_fragment>\nroughnessFactor=mix(.5,.28,smoothstep(.12,.7,vT));')
      .replace('#include <normal_fragment_maps>','#include <normal_fragment_maps>\nnormal=pNA(-vViewPosition,normal,vec2(dFdx(gH),dFdy(gH))*.0042);');
  };
  const m=new THREE.Mesh(g,mat);m.name='muscles';m.userData.uniforms=U;return m;};
});
